import React from 'react';
import { useNavigate } from 'react-router-dom';
import './LandingPage.css';

function LandingPage() {
  const navigate = useNavigate();

  return (
    <div className="landing-container">
      <div className="overlay">
        <h1 className="title">Welcome to the Diabetes Prediction System</h1>
        <p className="subtitle">Choose an option to begin:</p>
        <div className="button-container">
          <button onClick={() => navigate('/visualization')} className="landing-button">
            📊 Data Visualization
          </button>
          <button onClick={() => navigate('/prediction')} className="landing-button">
            🧠 Diabetes Prediction
          </button>
        </div>
      </div>
    </div>
  );
}

export default LandingPage;
